{% set demand = states('sensor.kotel_aktivni_zony_pocet') %}
{% set mode = states('input_select.topny_rezim') %}
{% set f = states('input_select.heating_flow_state_v4') %}
{% set ems = is_state('sensor.system_bus_status','connected') and is_state('binary_sensor.system_status','on') %}
{% set boost = is_state('binary_sensor.kotel_boost_active','on') %}
{% set phases = {'NORMAL':'Běžný provoz','EMERGENCY_COOLING':'Nouzové chlazení','RESTORING':'Obnova','HARD_LOCKOUT':'Blokace'} %}
<h2>Topení</h2>
<p><strong>{{ phases.get(f, 'Stav ochrany neověřen') }}</strong> · {{ mode if mode in ['Auto','Eco','Boost','Off'] else 'Režim neověřen' }} · {{ demand ~ ' z 8 místností žádá teplo' if is_number(demand) else 'Počet žádajících místností neověřen' }}</p>
{% if not ems %}<p><strong>Spojení s kotlem není potvrzené.</strong></p>{% endif %}
{% if boost %}<p><strong>Přitopení je aktivní.</strong></p>{% endif %}

<p><a href="/topeni-porovnani/schema"><ha-icon icon="mdi:home-outline"></ha-icon> Schéma domu</a> <a href="/topeni-porovnani/ochrana"><ha-icon icon="mdi:shield-outline"></ha-icon> Ochrany</a> <a href="/topeni-porovnani/predikce"><ha-icon icon="mdi:clock-outline"></ha-icon> Předtápění</a></p>

ha-card {
  border-radius:17px;
  border-color:color-mix(in srgb,var(--ha-color-teal-60,#0e6760) 18%,var(--card-background-color,white));
}
ha-markdown { padding:12px 14px !important; }

style.ha-markdown $:
ha-markdown-element > h2 { margin:0 0 8px; font-size:18px; line-height:1.24; }
ha-markdown-element p { line-height:1.45; }
ha-markdown-element > div:has(> table) { overflow:auto; }
ha-markdown-element table { width:100%; font-size:13px; }
ha-markdown-element th, ha-markdown-element td { text-align:start; }
ha-markdown-element a { color:light-dark(#0e6760,#77d6c7); }
ha-markdown-element a:focus-visible { outline:2px solid var(--primary-color); outline-offset:2px; }
ha-markdown-element > p:has(> a) { display:flex; flex-wrap:wrap; gap:4px 12px; }
ha-markdown-element p > a { display:inline-flex; align-items:center; min-height:44px; gap:5px; text-decoration:none; font-weight:700; }
ha-markdown-element p > a:hover { text-decoration:underline; }
ha-markdown-element p > a ha-icon { --mdc-icon-size:17px; }

cards.content:
{% set value = states('sensor.mi_air_purifier_2h_teplota') %}
{% set goal = state_attr('climate.sklep_michal', 'temperature') %}
{% set request = states('binary_sensor.zona_sklep_michal_aktivni') %}
{% set ok = is_state('binary_sensor.heating_valve_sklep_michal_alive', 'on') and has_value('climate.sklep_michal') %}
{% set manual = states('input_boolean.sklep_michal_manual_override') %}
{% set schedule = states('input_boolean.schedule_enable_sklep_michal') %}
{% set zone = 'sklep_michal' %}
{% set running = states('input_boolean.' ~ zone ~ '_schedule_active') %}
{% set mode = states('input_select.topny_rezim') %}
{% set end = namespace(minute=0) %}
{% if manual == 'off' and mode == 'Auto' and schedule == 'on' and running == 'on' %}
{% set z = 'sklep_michal' %}
{% set weekdays = ['mon','tue','wed','thu','fri','sat','sun'] %}
{% set today = now().weekday() %}
{% set ns = namespace(windows=[], rules=0) %}
{% for s in states.switch if s.entity_id.startswith('switch.schedule_') and s.state == 'on' %}
{% if ('input_boolean.' ~ z ~ '_schedule_active') in s.attributes.get('entities', []) %}
{% set ns.rules = ns.rules + 1 %}
{% set days = s.attributes.get('weekdays', []) %}
{% set prev = (today + 6) % 7 %}
{% set current_day = 'daily' in days or weekdays[today] in days or ('weekend' in days and today >= 5) or ('workday' in days and today < 5) %}
{% set previous_day = 'daily' in days or weekdays[prev] in days or ('weekend' in days and prev >= 5) or ('workday' in days and prev < 5) %}
{% set actions = s.attributes.get('actions', []) %}
{% for slot in s.attributes.get('timeslots', []) %}
{% set i = loop.index0 %}
{% set parts = slot.split(' - ') %}
{% if i < actions|length and actions[i].get('service') == 'input_boolean.turn_on' and parts|length == 2 and parts[0]|regex_match('^[0-9]{2}:[0-9]{2}(:[0-9]{2})?$') and parts[1]|regex_match('^[0-9]{2}:[0-9]{2}(:[0-9]{2})?$') %}
{% set start = (parts[0][:2]|int) * 60 + (parts[0][3:5]|int) %}
{% set end = (parts[1][:2]|int) * 60 + (parts[1][3:5]|int) %}
{% if 0 <= start < 1440 and 0 <= end <= 1440 %}
{% if current_day and end > start %}{% set ns.windows = ns.windows + [(start, end)] %}{% endif %}
{% if current_day and end < start %}{% set ns.windows = ns.windows + [(start, 1440)] %}{% endif %}
{% if previous_day and 0 < end < start %}{% set ns.windows = ns.windows + [(0, end)] %}{% endif %}
{% endif %}
{% endif %}
{% endfor %}
{% endif %}
{% endfor %}
{% set minute = now().hour * 60 + now().minute %}
{% for start, stop in ns.windows | sort %}
{% if (start <= minute < stop) or (end.minute and start <= end.minute < stop) %}
{% set end.minute = stop %}
{% endif %}
{% endfor %}
{% endif %}
{% set demand = 'Žádá teplo' if ok and request == 'on' else 'Bez požadavku' if ok and request == 'off' else 'Požadavek neověřen' %}
<div><ha-icon icon="mdi:radiator"></ha-icon><div>
<h2>Michal</h2>
<p><strong>{{ ('%.1f'|format(value|float)|replace('.', ',') ~ ' °C') if is_number(value) else '—' }}</strong> <small>Cíl {{ ('%.1f'|format(goal|float)|replace('.', ',') ~ ' °C') if ok and is_number(goal) else '—' }}</small></p>
</div></div>
<div><small>
{% if manual == 'on' %}Ruční režim
{% elif mode == 'Off' %}Topení vypnuté
{% elif mode == 'Eco' %}Centrální ECO
{% elif mode == 'Boost' %}Centrální Boost
{% elif manual == 'off' and mode == 'Auto' and schedule == 'on' and running == 'on' %}{{ 'Komfort do ' ~ ('%02d:%02d'|format(end.minute // 60, end.minute % 60)) if end.minute else 'Komfort podle rozvrhu' }}
{% elif manual == 'off' and mode == 'Auto' and schedule == 'on' and running == 'off' %}Útlum podle rozvrhu
{% else %}{{ demand }}
{% endif %}
</small><div><a href="/topeni-porovnani/sklep-michal">Proč netopí?</a> <a href="#den-sklep-michal"><ha-icon icon="mdi:calendar-blank-outline"></ha-icon> Rozvrh</a></div></div>

ha-card {
  --hp-room-accent: var(--ha-color-teal-60, #0e6760);
  --hp-room-accent: light-dark(#0e6760, #77d6c7);
  --hp-room-muted: var(--secondary-text-color, #4c615e);
  --hp-room-line: color-mix(in srgb, var(--hp-room-accent) 18%, var(--card-background-color, white));
  border-radius: 17px;
  border-color: var(--hp-room-line);
}
ha-markdown { padding: 10px 12px 0 !important; }

style.ha-markdown $:
ha-markdown-element { display: block; container-type: inline-size; }
ha-markdown-element > div:first-of-type { display: flex; align-items: center; gap: 9px; min-height: 45px; padding-bottom: 9px; }
ha-markdown-element > div:first-of-type > ha-icon { --mdc-icon-size: 22px; color: var(--hp-room-accent); flex: none; }
ha-markdown-element h2 { margin: 0 0 2px; font-size: 16px; font-weight: 750; line-height: 1.15; }
ha-markdown-element p { display: flex; align-items: baseline; gap: 5px; flex-wrap: wrap; margin: 0; line-height: 1.15; font-variant-numeric: tabular-nums; }
ha-markdown-element p strong { font-size: 23px; font-weight: 800; letter-spacing: -.045em; white-space: nowrap; }
ha-markdown-element small { color: var(--hp-room-muted); }
ha-markdown-element p small { font-size: 12px; white-space: nowrap; }
ha-markdown-element > div:last-of-type { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; column-gap: 7px; border-top: 1px solid var(--hp-room-line); min-height: 44px; }
ha-markdown-element > div:last-of-type > small { font-size: 13px; white-space: nowrap; }
ha-markdown-element > div:last-of-type > div { display: flex; align-items: center; margin-inline-start: auto; }
ha-markdown-element a { display: inline-flex; align-items: center; justify-content: center; gap: 4px; min-height: 44px; padding-inline: 6px; font-size: 13px; font-weight: 720; color: var(--hp-room-accent); text-decoration: none; white-space: nowrap; }
ha-markdown-element a:first-of-type { color: var(--hp-room-muted); }
ha-markdown-element a + a::before { content: ''; height: 14px; border-inline-start: 1px solid var(--hp-room-line); margin-inline-end: 3px; }
ha-markdown-element a ha-icon { --mdc-icon-size: 16px; }
ha-markdown-element a:hover { text-decoration: underline; }
ha-markdown-element a:focus-visible { outline: 2px solid var(--hp-room-accent); outline-offset: -2px; border-radius: 5px; }
@container (max-width: 280px) {
  ha-markdown-element > div:last-of-type > small { padding-block-start: 7px; }
  ha-markdown-element > div:last-of-type > div { margin-inline-start: 0; }
}

