{% set demand = states('binary_sensor.kotel_should_be_on') %}
{% set relay = states('switch.kotel_rele_spinac') %}
{% set flame = states('binary_sensor.boiler_burngas') %}
{% set link = is_state('sensor.system_bus_status','connected') and is_state('binary_sensor.system_status','on') %}
{% set code = states('sensor.boiler_servicecodenumber') %}
{% set active = states('sensor.kotel_aktivni_zony_pocet') %}
{% set minimum = states('sensor.kotel_effective_min_active_zones') %}
{% set f = states('input_select.heating_flow_state_v4') %}
{% set temp = states('sensor.boiler_curflowtemp') %}
{% set yn = {'on':'Ano','off':'Ne'} %}
{% set protection = {'NORMAL':'Běžný provoz','EMERGENCY_COOLING':'Nouzové chlazení','RESTORING':'Obnova','HARD_LOCKOUT':'Blokace'} %}
{% if f in ['EMERGENCY_COOLING','RESTORING','HARD_LOCKOUT'] %}
<h2>{{ protection[f] }}</h2>
{% elif not link %}
<h2>Spojení s kotlem vyžaduje kontrolu</h2>
{% elif link and flame == 'on' and relay == 'off' %}
<h2>Stav kotle vyžaduje kontrolu</h2>
{% elif code in ['2964','2965','2966','2967'] %}
<h2>Kotel hlásí poruchu {{ code }}</h2>
{% elif is_state('input_boolean.heating_service_mode','on') %}
<h2>Servisní režim</h2>
{% elif is_state('input_boolean.topny_system_enable','off') or is_state('input_select.topny_rezim','Off') %}
<h2>Automatické vytápění je vypnuté</h2>
{% elif demand not in yn or relay not in yn or flame not in yn or f not in protection %}
<h2>Část provozních údajů je nedostupná</h2>
{% elif flame == 'on' %}
<h2>Hořák běží</h2>
{% elif relay == 'on' %}
<h2>Topné relé je sepnuté</h2>
{% elif demand == 'on' %}
<h2>Řízení žádá topení</h2>
{% else %}
<h2>Řízení právě nežádá topení</h2>
{% endif %}
<div>
{% for label, state, on, off in [('Požadavek', demand, 'Žádá', 'Klid'), ('Relé', relay, 'Sepnuto', 'Rozepnuto'), ('Hořák', flame if link else 'unknown', 'Hoří', 'Nehoří')] %}
<div><small>{{ label }}</small> <strong>{% if state == 'on' %}<em>{{ on }}</em>{% else %}{{ off if state == 'off' else 'Neověřeno' }}{% endif %}</strong></div>
{% endfor %}
</div>
<div>
<div><small>Výstupní voda</small> <strong>{{ ('%.1f'|format(temp|float)|replace('.', ',') ~ ' °C') if link and is_number(temp) else '—' }}</strong></div>
<div><small>Žádající zóny / min.</small> <strong>{{ active if is_number(active) else '—' }} / {{ minimum if is_number(minimum) else '—' }}</strong></div>
</div>
<p>{{ {'Auto':'Auto','Eco':'Eco','Boost':'Boost','Off':'Vypnuto'}.get(states('input_select.topny_rezim'),'Režim neověřen') }} <span>· {{ protection.get(f,'Ochrana neověřena') }}</span></p>
{% if link and flame == 'on' and relay == 'off' %}<p><strong>Hořák běží při rozepnutém relé.</strong></p>{% endif %}
<div><a href="/topeni-porovnani/kotel">Detail kotle</a> <a href="/topeni-porovnani/ochrana">Ochrany</a></div>

