cards.content:
{% set zones = [["sklep_michal", "Sklep · Michal"], ["prizemi_michal", "Přízemí · Michal"], ["prizemi_chodba_zachod", "Přízemí · Chodba / WC"], ["1p_kuchyn", "Kuchyň"], ["1p_jidelna", "Jídelna"], ["1p_chodba", "Chodba"], ["1p_koupelna", "Koupelna"], ["2p_mama", "2. patro · Máma"]] %}
{% set ns=namespace(lines=[]) %}
{% for e,label in [('binary_sensor.heating_core_v4_healthy','Automatizace řízení'),('binary_sensor.heating_dispatch_inputs_available','Vstupy řízení'),('binary_sensor.system_status','Spojení s kotlem')] %}
{% if not is_state(e,'on') %}{% set ns.lines=ns.lines+['- **' ~ label ~ ':** ' ~ ('problém / výpadek.' if is_state(e,'off') else 'stav neznámý.')] %}{% endif %}
{% endfor %}
{% for e,label in [('input_boolean.topny_system_enable','Hlavní řízení'),('input_boolean.heating_central_dispatch_enable','Předávání teplot do hlavic')] %}
{% if not is_state(e,'on') %}{% set ns.lines=ns.lines+['- **' ~ label ~ ':** ' ~ ('vypnuté.' if is_state(e,'off') else 'stav neznámý.')] %}{% endif %}
{% endfor %}
{% for z,name in zones %}
{% set c='climate.' ~ z %}{% set a='sensor.' ~ z ~ '_stav_adaptacniho_behu' %}{% set err='sensor.' ~ z ~ '_chyba_softwaru' %}
{% if not has_value(c) or not is_state('binary_sensor.heating_valve_' ~ z ~ '_alive','on') %}
{% set ns.lines=ns.lines+['- **' ~ name ~ ':** hlavice nemá ověřená aktuální data.'] %}
{% endif %}
{% if not has_value(err) %}{% set ns.lines=ns.lines+['- **' ~ name ~ ':** diagnostika závad není dostupná.'] %}
{% elif is_state(err,'something') %}{% set ns.lines=ns.lines+['- **' ~ name ~ ':** hlavice hlásí závadu; otevři detail.'] %}{% endif %}
{% if not has_value(a) %}{% set ns.lines=ns.lines+['- **' ~ name ~ ':** stav adaptace není dostupný.'] %}
{% elif state_attr(a,'In_progress') == true %}{% set ns.lines=ns.lines+['- **' ~ name ~ ':** probíhá adaptace ventilu.'] %}
{% elif state_attr(a,'Valve_characteristic_lost') == true %}{% set ns.lines=ns.lines+['- **' ~ name ~ ':** charakteristika ventilu byla ztracena.'] %}
{% elif state_attr(a,'Valve_characteristic_found') != true %}{% set ns.lines=ns.lines+['- **' ~ name ~ ':** adaptace ventilu není potvrzená.'] %}{% endif %}
{% endfor %}
{% if is_state('input_boolean.heating_startup_reconcile_guard','on') %}{% set ns.lines=ns.lines+['- Probíhá obnova řízení po startu.'] %}{% endif %}
{% if is_state('sensor.kotel_efficiency_rating','Kritické cyklování!') %}
{% set ns.lines=ns.lines+['- **Cyklování:** stávající diagnostika hodnotí posledních 24 h jako kritické. Nejde o měřenou účinnost.'] %}
{% elif not has_value('sensor.kotel_efficiency_rating') %}{% set ns.lines=ns.lines+['- Hodnocení cyklování není dostupné.'] %}{% endif %}
## {{ 'Vyžaduje pozornost' if ns.lines else 'Diagnostika bez hlášených problémů' }}
{{ ns.lines | join('
') if ns.lines else 'Kontrolované automatizace, spojení a diagnostika hlavic jsou v pořádku.' }}

