{% set z = 'prizemi_michal' %}
{% set weekdays = ['mon','tue','wed','thu','fri','sat','sun'] %}
{% set names = ['Pondělí','Úterý','Středa','Čtvrtek','Pátek','Sobota','Neděle'] %}
{% set found = namespace(rules=[]) %}
{% for s in states.switch if s.entity_id.startswith('switch.schedule_') and s.state == 'on' %}
{% if ('input_boolean.' ~ z ~ '_schedule_active') in s.attributes.get('entities', []) %}
{% set found.rules = found.rules + [s] %}
{% endif %}
{% endfor %}
{% set rules = found.rules %}
## Týdenní rozvrh

{% if is_state('input_boolean.schedule_enable_' ~ z, 'off') %}Rozvrh zóny je pozastavený. Níže jsou uložená okna zapnutých pravidel.

{% endif %}
{% if rules %}
{% set week = namespace(rows=[]) %}
{% for today in range(7) %}
{% set ns = namespace(windows=[]) %}

{% for s in rules %}
{% set days = s.attributes.get('weekdays', []) %}
